// Español (España) UI catalog — partial by design (owner 2026-10-13: periodic translation; normal
// development maintains only zh-CN + en). Missing keys fall back to en at lookup time
// (i18n/index.tsx); `...modulesEn` first keeps every key present, the entries below override.
//
// Glosario (mantener la coherencia): Profile → perfil · Settings → Ajustes · Appearance → Aspecto ·
// turn → turno · step → paso · host → host · runtime → runtime (plural runtimes) · release →
// versión · queue → cola / en cola · steer/insert → insertar / redirigir · delegation → delegación ·
// wake → despertar · note → nota · alarm → alarma · approval → aprobación · bookmark → marcador ·
// quota → cuota · usage limit → límite de uso · credits → créditos · jobs → trabajos (Job Service) ·
// task service → Servicio de tareas · workflow → flujo de trabajo · run plan → plan de ejecución ·
// skill → habilidad (hook/plugin/MCP/diff/relay/preset/endpoint/daemon/token: sin traducir) ·
// quick launch → Inicio rápido · side chat → conversación lateral · roll back → revertir /
// reversión · one-way → en un solo sentido · preflight → comprobación previa · idle → inactivo ·
// busy → ocupado / trabajando · online/offline → en línea / sin conexión · archive → archivar ·
// restore → restaurar · fork → bifurcar · device → dispositivo · computer → equipo · tray →
// bandeja · sidebar → barra lateral · right column → columna derecha · picture → imagen ·
// Enter/Shift/Space → Intro/Mayús/Espacio · «…» para nombres y elementos de menú.
