  "claude-science.removeConfirm": "¿Quitar la cuenta {name}? Su Claude Science se detiene y se desregistra de cutex. El directorio de la cuenta {home} se conserva y no se borra; añádela de nuevo con el mismo directorio para continuar donde lo dejaste.",
