  "claude-science.form.home": "Directorio de la cuenta (en el host)",
  "claude-science.form.homeHint": "El HOME de la cuenta, se crea si falta. Un directorio existente conserva una cuenta que ya tiene la sesión iniciada (detén antes esa cuenta donde sea que se ejecute). Como máximo 41 caracteres (un límite de Claude Science). Quitar la cuenta nunca lo borra.",
