  "claude-science.otherHost": "Las cuentas de este host se abren en la pestaña del navegador propia de este host: abre antes uno de los {{agents}} de este host y vuelve a pulsar Abrir",
  "claude-science.login.title": "Primer inicio de sesión",
  "claude-science.login.step1": "Pulsa Abrir: el navegador integrado abre la cuenta en la página local de inicio de sesión de Claude Science (un enlace de un solo uso, recreado en cada apertura). Pulsa Sign in.",
  "claude-science.login.step2": "Dentro, pulsa Sign in on the web e inicia sesión con esta cuenta en claude.ai. Si claude.ai muestra otra cuenta, cambia de cuenta o cierra sesión primero; también puedes hacer este paso en otro navegador donde esta cuenta tenga la sesión iniciada.",
  "claude-science.login.step3": "claude.ai muestra entonces un código de autorización: cópialo y pégalo en Claude Science (Paste code).",
  "claude-science.login.step4": "Claude Science se reinicia una vez solo (es lo esperado; cutex lo sigue). La cuenta queda entonces con la sesión iniciada; en aperturas posteriores pulsa Sign in o Continue.",
  "claude-science.login.why": "Cada cuenta inicia sesión una vez en su propio directorio, no con el inicio de sesión de Claude de un perfil de cutex: compartirlo haría que los tokens de refresco se expulsaran mutuamente.",
