  "pane.tray.persistentHint": "Activado: una franja baja en su borde y los paneles le dejan sitio. Desactivado: oculta tras una pequeña asa mientras haya paneles abiertos; pasa el ratón por encima, haz clic o pulsa {key}",
  "pane.tray.edge": "Posición de la bandeja",
  "pane.tray.edgeHint": "O arrastra la bandeja por su asa hasta un borde de la ventana, o elige «Acoplar en» en su menú contextual",
  "workSurface.width": "Ancho del espacio de trabajo",
  "workSurface.widthHint": "Inteligente (predeterminado): con un espacio de trabajo, según el contenido; con dos, llenan la ventana y las conversaciones se reparten el ancho a partes iguales, con el divisor entre ellas para arrastrar. Según el contenido: la columna de conversación y su {{shelf}} conservan cada uno su ancho, centrados juntos, con el escritorio a ambos lados; si la ventana es demasiado estrecha, primero los {{shelves}} se pliegan a su Rail y luego se estrechan las columnas. Llenar la ventana: los espacios de trabajo ocupan toda la ventana, de borde a borde, sin escritorio (antes «Llenar toda la ventana cuando los paneles la llenan»)",
  "workSurface.width.content": "Según el contenido",
  "workSurface.width.fill": "Llenar la ventana",
  "workSurface.wsRails": "Posición del {{shelf}} lado a lado",
  "workSurface.wsRailsHint": "Con dos espacios de trabajo lado a lado: Bordes exteriores = el {{shelf}} del espacio izquierdo en el borde izquierdo de la ventana y el del derecho en el borde derecho, nunca entre las dos conversaciones; Siempre a la derecha = el {{shelf}} de cada espacio de trabajo a su derecha. Con un solo espacio de trabajo, el {{shelf}} se queda en su propio lado",
  "workSurface.wsRails.outer": "Bordes exteriores",
  "workSurface.wsRails.right": "Siempre a la derecha",
  "workSurface.shelfRail": "Posición del {{Shelf}} Rail",
  "workSurface.shelfRailHint": "El Rail en el lado del {{shelf}} junto a la ventana (exterior) o junto a la conversación (interior). Esto ajusta todos los {{shelf}} y los nuevos; el ⋯ de cada {{shelf}} aún puede cambiar el suyo",
  "workSurface.shelfRailAlways": "Mostrar siempre el {{Shelf}} Rail",
  "workSurface.shelfRailAlwaysHint": "El {{Shelf}} Rail de cada conversación se queda en su sitio, también cuando el {{shelf}} está cerrado o vacío (vacío: el avatar y ＋ para abrir algo). Desactivado: un {{shelf}} vacío no tiene rail y un {{shelf}} cerrado no muestra nada",
