  "workSurface.edge": "De borde a borde",
  "workSurface.edgeHint": "Mientras los paneles llenan el área de trabajo, quita los huecos entre las tarjetas, los márgenes a su alrededor y sus esquinas exteriores: sin escritorio. Desactivado: llenar la ventana conserva las esquinas, los huecos y las sombras",
  "workSurface.widthRules": "Inteligente (predeterminado): con un espacio de trabajo, según el contenido; con dos, llenan la ventana y las conversaciones se reparten el ancho en la proporción que arrastraste por última vez. Según el contenido: la columna de conversación y su {{shelf}} conservan cada uno su ancho, centrados juntos, con el escritorio a ambos lados. Llenar la ventana: las columnas se reparten todo el ancho de la ventana. Esto solo ajusta anchos; las tarjetas conservan sus esquinas, huecos y sombras (de borde a borde es un ajuste aparte, más abajo). Arrastrar el borde entre dos paneles solo cambia esos dos; doble clic para sus valores predeterminados; mover el foco nunca cambia la disposición",
