  "browser.controlPaused": "En pausa · haz clic en Reanudar para continuar",
  "browser.externalPages.hint": "Activado: las pestañas del navegador integrado acceden a internet a través de un proxy local exclusivo del navegador (solo 127.0.0.1, una credencial nueva en cada ejecución, sin descifrar HTTPS, sin caché; se cierra con la última pestaña o al salir de la aplicación). Solo las pestañas del navegador pueden usarlo: la ventana de la aplicación, los plugins y las páginas de artefactos siguen sin red. Al desactivarlo se cortan al momento las conexiones abiertas a sitios web. Las direcciones de LAN / tailnet no dependen de este interruptor: una dirección que abres en la barra de direcciones funciona solo en esa pestaña, y las páginas no pueden acceder por su cuenta a otras direcciones de LAN o locales.",
